			logError(`Shutting down gracefully after ${signal}`);
			let shutdownFailed = false;
			let shutdownError: unknown;

			try {
				await target.close();
			} catch (error) {
				shutdownFailed = true;
				shutdownError = error;
			}

			try {
				await flush();
			} catch (error) {
				if (!shutdownFailed) {
					shutdownError = error;
				}
				shutdownFailed = true;
			}

